app.MapGet("/api/public/tournaments/{tid:int}/fixtures", async (int tid, AppDbContext db) => { var fixtures=await db.Fixtures.Where(x=>x.TournamentId==tid).OrderBy(x=>x.RoundNo).ThenBy(x=>x.Slot).ToListAsync(); var ids=fixtures.SelectMany(x=>new[]{x.HomeTeamId,x.AwayTeamId}).Where(x=>x.HasValue).Select(x=>x!.Value).Distinct().ToArray(); var names=await db.Teams.Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name); return Results.Ok(fixtures.Select(x=>new { x.Id,x.TournamentId,x.RoundNo,x.Slot,x.Status,x.StartsAt,x.Venue,x.HomeScore,x.AwayScore,x.Outcome,x.WinnerTeamId,HomeTeam=x.HomeTeamId.HasValue&&names.TryGetValue(x.HomeTeamId.Value,out var home)?home:null,AwayTeam=x.AwayTeamId.HasValue&&names.TryGetValue(x.AwayTeamId.Value,out var away)?away:null })); }).AllowAnonymous();
