app.MapGet("/api/public/leaderboards/overall", async (AppDbContext db) => Results.Ok(await PublicLeaderboardAsync(db,null))).AllowAnonymous();
app.MapGet("/api/public/statistics/{sportId:int}", async (int sportId, AppDbContext db) => { var tournaments=await db.Tournaments.Where(x=>x.SportId==sportId).Select(x=>x.Id).ToListAsync(); var fixtures=await db.Fixtures.Where(x=>tournaments.Contains(x.TournamentId)).ToListAsync(); return Results.Ok(new { sportId,TournamentCount=tournaments.Count,TeamCount=await db.Teams.CountAsync(x=>tournaments.Contains(x.TournamentId)&&x.Status==TeamStatus.Approved),FixtureCount=fixtures.Count,CompletedMatches=fixtures.Count(x=>x.Status==FixtureStatus.Completed),ScheduledMatches=fixtures.Count(x=>x.Status==FixtureStatus.Scheduled),PendingMatches=fixtures.Count(x=>x.Status==FixtureStatus.Pending),Walkovers=fixtures.Count(x=>x.Status==FixtureStatus.Walkover),Draws=fixtures.Count(x=>string.Equals(x.Outcome,"draw",StringComparison.OrdinalIgnoreCase)) }); }).AllowAnonymous();

var auth=app.MapGroup("/api").RequireAuthorization();
auth.MapGet("/sports", async (AppDbContext db) => Results.Ok(await db.Sports.OrderBy(x=>x.Name).ToListAsync()));
auth.MapGet("/tournaments", async (AppDbContext db) => Results.Ok(await db.Tournaments.Include(x=>x.Sport).OrderByDescending(x=>x.Id).Select(x=>new { x.Id,x.Name,x.Status,x.RegistrationOpen,x.SportId,SportName=x.Sport!.Name,x.StartAt,x.EndAt,TeamCount=x.Teams.Count(t=>t.Status==TeamStatus.Approved),FixtureCount=x.Fixtures.Count }).ToListAsync()));
auth.MapPost("/sports", async (SportRequest request, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); if(string.IsNullOrWhiteSpace(request.Name)) return Results.BadRequest(new { message="Sport name is required" }); if(await db.Sports.AnyAsync(x=>x.Name==request.Name.Trim())) return Results.Conflict(new { message="A sport with this name already exists" }); var sport=new Sport{Name=request.Name.Trim(),RulesJson=request.Rules is null?"{}":JsonSerializer.Serialize(request.Rules)}; db.Sports.Add(sport); await db.SaveChangesAsync(); await Audit(db,claims,"create","sport",sport.Id,new { sport.Name }); return Results.Ok(sport); });
auth.MapPut("/sports/{id:int}", async (int id, SportRequest request, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var sport=await db.Sports.FindAsync(id); if(sport is null) return Results.NotFound(); if(string.IsNullOrWhiteSpace(request.Name)) return Results.BadRequest(new { message="Sport name is required" }); sport.Name=request.Name.Trim(); sport.RulesJson=request.Rules is null?sport.RulesJson:JsonSerializer.Serialize(request.Rules); await db.SaveChangesAsync(); await Audit(db,claims,"update","sport",id,request); return Results.Ok(sport); });
auth.MapPut("/tournaments/{id:int}", async (int id, TournamentUpdateRequest request, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var t=await db.Tournaments.FindAsync(id); if(t is null) return Results.NotFound(); if(!await db.Sports.AnyAsync(x=>x.Id==request.SportId)) return Results.NotFound(new { message="Sport not found" }); t.SportId=request.SportId; t.Name=request.Name.Trim(); t.Status=string.IsNullOrWhiteSpace(request.Status)?t.Status:request.Status.Trim(); t.RegistrationOpen=request.RegistrationOpen; t.StartAt=request.StartAt; t.EndAt=request.EndAt; t.ThirdPlace=request.ThirdPlace; t.MatchStartTime=request.MatchStartTime; t.MatchEndTime=request.MatchEndTime; t.AvailableDatesJson=JsonSerializer.Serialize(request.AvailableDates??[]); t.VenueIdsJson=JsonSerializer.Serialize(request.VenueIds??[]); t.Version++; await db.SaveChangesAsync(); await Audit(db,claims,"update","tournament",id,request); return Results.Ok(t); });
auth.MapGet("/leaderboards/{sportId:int}", async (int sportId, AppDbContext db) => Results.Ok(await db.Teams.Include(x=>x.Tournament).Where(x=>x.Tournament!.SportId==sportId).GroupBy(x=>x.Department).Select(g=>new { Department=g.Key, Wins=db.Fixtures.Count(f=>f.WinnerTeamId!=null && g.Select(t=>t.Id).Contains(f.WinnerTeamId.Value)), Points=db.Fixtures.Count(f=>f.WinnerTeamId!=null && g.Select(t=>t.Id).Contains(f.WinnerTeamId.Value))*3 }).OrderByDescending(x=>x.Points).ToListAsync()));
