auth.MapGet("/captain/teams", async (ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Captain)) return Results.Forbid(); var id=UserId(claims); return Results.Ok(await db.Teams.Include(x=>x.Tournament).ThenInclude(x=>x!.Sport).Where(x=>x.CaptainId==id).OrderByDescending(x=>x.Id).Select(x=>new { x.Id,x.Name,x.Department,x.Section,Status=x.Status.ToString(),x.ReviewReason,TournamentId=x.TournamentId,TournamentName=x.Tournament!.Name,SportName=x.Tournament!.Sport!.Name }).ToListAsync()); });
auth.MapGet("/captain/fixtures", async (ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Captain)) return Results.Forbid(); var id=UserId(claims); var teamIds=await db.Teams.Where(x=>x.CaptainId==id).Select(x=>x.Id).ToListAsync(); return Results.Ok(await db.Fixtures.Where(x=>x.HomeTeamId.HasValue&&x.AwayTeamId.HasValue&&(teamIds.Contains(x.HomeTeamId.Value)||teamIds.Contains(x.AwayTeamId.Value))).Include(x=>x.Tournament).OrderBy(x=>x.StartsAt).Select(x=>new { x.Id,x.TournamentId,TournamentName=x.Tournament!.Name,x.RoundNo,x.Slot,x.Status,x.StartsAt,x.Venue,x.HomeScore,x.AwayScore,x.Outcome,x.Version }).ToListAsync()); });
auth.MapGet("/admin/teams", async (string? status, int? tournamentId, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var query=db.Teams.Include(x=>x.Tournament).ThenInclude(x=>x!.Sport).AsQueryable(); if(tournamentId.HasValue) query=query.Where(x=>x.TournamentId==tournamentId.Value); if(Enum.TryParse<TeamStatus>(status,true,out var parsed)) query=query.Where(x=>x.Status==parsed); return Results.Ok(await query.OrderBy(x=>x.Status).ThenBy(x=>x.Id).Select(x=>new { x.Id,x.Name,x.Department,x.Section,Status=x.Status.ToString(),x.ReviewReason,TournamentId=x.TournamentId,TournamentName=x.Tournament!.Name,SportName=x.Tournament!.Sport!.Name }).ToListAsync()); });

auth.MapPost("/tournaments", async (TournamentRequest request, ClaimsPrincipal claims, AppDbContext db) =>
{
    if(!IsRole(claims,UserRole.Admin)) return Results.Forbid();
    if(!await db.Sports.AnyAsync(x=>x.Id==request.SportId)) return Results.NotFound(new { message="Sport not found" });
    var t=new Tournament { SportId=request.SportId,Name=request.Name,StartAt=request.StartAt,EndAt=request.EndAt,ThirdPlace=request.ThirdPlace,MatchStartTime=request.MatchStartTime,MatchEndTime=request.MatchEndTime,AvailableDatesJson=JsonSerializer.Serialize(request.AvailableDates??[]),VenueIdsJson=JsonSerializer.Serialize(request.VenueIds??[]) };
    db.Tournaments.Add(t); await db.SaveChangesAsync(); await Audit(db,claims,"create","tournament",t.Id,request); return Results.Ok(t);
});
auth.MapGet("/admin/dashboard", async (ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); return Results.Ok(new { totalTeams=await db.Teams.CountAsync(), approvedTeams=await db.Teams.CountAsync(x=>x.Status==TeamStatus.Approved), pendingTeams=await db.Teams.CountAsync(x=>x.Status==TeamStatus.Pending), withdrawnTeams=await db.Teams.CountAsync(x=>x.Status==TeamStatus.Withdrawn), tournaments=await db.Tournaments.CountAsync(), fixtures=await db.Fixtures.CountAsync(), completedFixtures=await db.Fixtures.CountAsync(x=>x.Status==FixtureStatus.Completed), games=await db.Sports.Select(s=>new { s.Id,s.Name,TotalTeams=db.Teams.Count(t=>t.Tournament!.SportId==s.Id) }).ToListAsync() }); });

auth.MapPost("/tournaments/{tid:int}/teams", async (int tid, TeamRequest request, ClaimsPrincipal claims, AppDbContext db) =>
{
    if(!IsRole(claims,UserRole.Captain)) return Results.Forbid(); var user=await db.Users.FindAsync(UserId(claims)); var t=await db.Tournaments.FindAsync(tid); if(user is null||t is null||!t.RegistrationOpen) return Results.NotFound(new { message="Tournament is not open for registration" }); if(!user.EmailVerified) return Results.BadRequest(new { message="Verify your Gmail address before registering a team" });
    if(await db.Teams.AnyAsync(x=>x.TournamentId==tid&&x.Name==request.Name)) return Results.Conflict(new { message="Team name already exists" });
    var playerIds=(request.PlayerIds??[]).Append(user.Id).Distinct().ToList(); var already=await db.TeamPlayers.Where(x=>playerIds.Contains(x.UserId)&&x.Team!.TournamentId==tid).Select(x=>x.UserId).ToListAsync(); if(already.Count>0) return Results.Conflict(new { message="A player is already registered in this tournament", playerIds=already });
    var team=new Team { TournamentId=tid,Name=request.Name,Department=user.Department,Section=request.Section,CaptainId=user.Id,CaptainPhone=request.CaptainPhone }; db.Teams.Add(team); await db.SaveChangesAsync(); foreach(var pid in playerIds) db.TeamPlayers.Add(new TeamPlayer{TeamId=team.Id,UserId=pid}); await db.SaveChangesAsync(); return Results.Ok(team);
});
auth.MapPost("/registrations/{teamId:int}/approve", async (int teamId, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var t=await db.Teams.FindAsync(teamId); if(t is null)return Results.NotFound(); t.Status=TeamStatus.Approved; t.ReviewReason=null; await db.SaveChangesAsync(); await Audit(db,claims,"approve","team",teamId,new{}); return Results.Ok(new { status=t.Status.ToString(),teamId }); });
auth.MapPost("/registrations/{teamId:int}/reject", async (int teamId, ReviewTeamRequest request, ClaimsPrincipal claims, AppDbContext db) => { if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var t=await db.Teams.FindAsync(teamId); if(t is null)return Results.NotFound(); if(t.Status!=TeamStatus.Pending)return Results.Conflict(new { message="Only pending registrations can be rejected" }); t.Status=TeamStatus.Rejected; t.ReviewReason=string.IsNullOrWhiteSpace(request.Reason)?"Registration requires correction":request.Reason.Trim(); await db.SaveChangesAsync(); await Audit(db,claims,"reject","team",teamId,request); return Results.Ok(new { status=t.Status.ToString(),teamId,reason=t.ReviewReason }); });

auth.MapPost("/tournaments/{tid:int}/generate-fixtures", async (int tid, ClaimsPrincipal claims, AppDbContext db) =>
{
    if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var t=await db.Tournaments.FindAsync(tid); if(t is null)return Results.NotFound(); if(await db.Fixtures.AnyAsync(x=>x.TournamentId==tid&&new[]{FixtureStatus.Completed,FixtureStatus.Walkover,FixtureStatus.DoubleForfeit,FixtureStatus.Abandoned}.Contains(x.Status))) return Results.Conflict(new{message="Fixtures cannot be regenerated after historical matches exist. Use the withdrawal/regeneration workflow to preserve history."}); var ids=await db.Teams.Where(x=>x.TournamentId==tid&&x.Status==TeamStatus.Approved).OrderBy(x=>x.Id).Select(x=>x.Id).ToListAsync(); if(ids.Count<2)return Results.BadRequest(new{message="At least two approved teams are required"}); db.Fixtures.RemoveRange(db.Fixtures.Where(x=>x.TournamentId==tid)); foreach(var p in TournamentEngine.GenerateBracket(ids)) db.Fixtures.Add(new Fixture{TournamentId=tid,RoundNo=p.RoundNo,Slot=p.Slot,HomeTeamId=p.Home,AwayTeamId=p.Away,Status=p.Bye?FixtureStatus.Bye:FixtureStatus.Pending,WinnerTeamId=p.Bye?(p.Home??p.Away):null}); t.Status="Scheduled";t.RegistrationOpen=false;t.Version++; await db.SaveChangesAsync(); await Audit(db,claims,"generate-fixtures","tournament",tid,new{teamCount=ids.Count}); return Results.Ok(new{tournamentId=tid,fixtureCount=await db.Fixtures.CountAsync(x=>x.TournamentId==tid)});
});
auth.MapGet("/tournaments/{tid:int}/fixtures", async(int tid, AppDbContext db)=>{var fixtures=await db.Fixtures.Where(x=>x.TournamentId==tid).OrderBy(x=>x.RoundNo).ThenBy(x=>x.Slot).ToListAsync();var ids=fixtures.SelectMany(x=>new[]{x.HomeTeamId,x.AwayTeamId}).Where(x=>x.HasValue).Select(x=>x!.Value).Distinct().ToArray();var names=await db.Teams.Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name);return Results.Ok(fixtures.Select(x=>new{x.Id,x.TournamentId,x.RoundNo,x.Slot,x.Status,x.StartsAt,x.Venue,x.HomeScore,x.AwayScore,x.Outcome,x.WinnerTeamId,x.Version,HomeTeam=x.HomeTeamId.HasValue&&names.TryGetValue(x.HomeTeamId.Value,out var home)?home:null,AwayTeam=x.AwayTeamId.HasValue&&names.TryGetValue(x.AwayTeamId.Value,out var away)?away:null}));});

auth.MapPost("/tournaments/{tid:int}/auto-schedule", async(int tid, AutoScheduleRequest request, ClaimsPrincipal claims, AppDbContext db, IEmailSender email)=>
{
    if(!IsRole(claims,UserRole.Admin))return Results.Forbid(); var t=await db.Tournaments.Include(x=>x.Sport).SingleOrDefaultAsync(x=>x.Id==tid); if(t is null)return Results.NotFound(); var pending=await db.Fixtures.Where(x=>x.TournamentId==tid&&new[]{FixtureStatus.Pending,FixtureStatus.Scheduled}.Contains(x.Status)&&x.HomeTeamId!=null&&x.AwayTeamId!=null).OrderBy(x=>x.RoundNo).ThenBy(x=>x.Slot).ToListAsync(); var rules=JsonSerializer.Deserialize<JsonElement>(t.Sport!.RulesJson); var duration=request.DurationMinutes??(rules.TryGetProperty("durationMinutes",out var d)?d.GetInt32():60); List<ScheduleAssignment> assignments; try{assignments=TournamentEngine.BuildSchedule(pending.Select(x=>(x.Id,x.DurationMinutes)),request.MatchStartTime,request.MatchEndTime,request.AvailableDates,request.Venues,duration);}catch(ArgumentException e){return Results.BadRequest(new{message=e.Message});} foreach(var a in assignments){var f=pending.Single(x=>x.Id==a.FixtureId);f.StartsAt=a.StartsAt;f.Venue=a.Venue;f.DurationMinutes=duration;f.Status=FixtureStatus.Scheduled;f.Version++;} await db.SaveChangesAsync(); foreach(var a in assignments) await SendFixtureEmailAsync(db,email,a.FixtureId,"Upcoming SportsWeek match",true); await Audit(db,claims,"auto-schedule","tournament",tid,new{scheduled=assignments.Count,duration}); return Results.Ok(new{scheduled=assignments.Count,durationMinutes=duration});
});

auth.MapPost("/fixtures/{fid:int}/schedule", async(int fid, ScheduleRequest request, ClaimsPrincipal claims, AppDbContext db, IEmailSender email)=>
{
    if(!IsRole(claims,UserRole.Admin,UserRole.Scorer))return Results.Forbid(); var f=await db.Fixtures.FindAsync(fid); if(f is null)return Results.NotFound(); if(f.Version!=request.ExpectedVersion)return Results.Conflict(new{message="Schedule changed by another user"}); var other=await db.Fixtures.Where(x=>x.TournamentId==f.TournamentId&&x.Id!=fid&&x.StartsAt!=null).ToListAsync(); var clashes=other.Where(x=>x.StartsAt<request.StartsAt.AddMinutes(f.DurationMinutes)&&request.StartsAt<x.StartsAt!.Value.AddMinutes(x.DurationMinutes)&&(x.Venue==request.Venue||x.HomeTeamId==f.HomeTeamId||x.HomeTeamId==f.AwayTeamId||x.AwayTeamId==f.HomeTeamId||x.AwayTeamId==f.AwayTeamId)).Select(x=>x.Venue==request.Venue?"venue clash":"team clash").Distinct().ToList(); if(clashes.Count>0&&!request.Override)return Results.Conflict(new{message="Schedule clash",conflicts=clashes}); f.StartsAt=request.StartsAt;f.Venue=request.Venue;f.Status=FixtureStatus.Scheduled;f.Version++;await db.SaveChangesAsync();await Audit(db,claims,"schedule-fixture","fixture",fid,new{request.Override,clashes});await SendFixtureEmailAsync(db,email,fid,"Upcoming SportsWeek match",true);return Results.Ok(new{fixtureId=fid,f.Version,conflicts=clashes});
});

auth.MapPost("/fixtures/{fid:int}/score", async(int fid, ScoreRequest request, ClaimsPrincipal claims, AppDbContext db, IEmailSender email)=>
{
    if(!IsRole(claims,UserRole.Admin,UserRole.Scorer))return Results.Forbid(); var f=await db.Fixtures.FindAsync(fid); if(f is null)return Results.NotFound(); if(f.HomeTeamId is null||f.AwayTeamId is null)return Results.BadRequest(new{message="This fixture is waiting for both participating teams to advance."}); if(f.Version!=request.ExpectedVersion)return Results.Conflict(new{message="Result changed by another scorer"}); if(f.Status is not(FixtureStatus.Pending or FixtureStatus.Scheduled))return Results.Conflict(new{message="Fixture is already resolved"}); try{f.WinnerTeamId=TournamentEngine.Winner(f.HomeTeamId,f.AwayTeamId,request.HomeScore,request.AwayScore,request.Status);}catch(ArgumentException e){return Results.BadRequest(new{message=e.Message});} f.HomeScore=request.HomeScore;f.AwayScore=request.AwayScore;f.Outcome=request.Outcome;f.Status=Enum.TryParse<FixtureStatus>(request.Status,true,out var st)?st:FixtureStatus.Completed;f.Version++;if(f.WinnerTeamId.HasValue)await AdvanceWinnerAsync(db,f,f.WinnerTeamId.Value);await db.SaveChangesAsync();await Audit(db,claims,"score-fixture","fixture",fid,request);await SendFixtureEmailAsync(db,email,fid,"SportsWeek result posted",false);return Results.Ok(new{fixtureId=fid,winnerTeamId=f.WinnerTeamId,version=f.Version});
});

auth.MapPost("/teams/{teamId:int}/withdraw", async(int teamId, ClaimsPrincipal claims, AppDbContext db)=>
{
    if(!IsRole(claims,UserRole.Admin))return Results.Forbid(); var team=await db.Teams.Include(x=>x.Tournament).SingleOrDefaultAsync(x=>x.Id==teamId); if(team is null)return Results.NotFound(); if(team.Status!=TeamStatus.Approved)return Results.BadRequest(new{message="Only an approved team can be withdrawn."}); team.Status=TeamStatus.Withdrawn; team.Tournament!.Version++; var fixtures=await db.Fixtures.Where(x=>(x.HomeTeamId==teamId||x.AwayTeamId==teamId)&&x.Status==FixtureStatus.Pending).ToListAsync(); foreach(var f in fixtures){f.WinnerTeamId=f.HomeTeamId==teamId?f.AwayTeamId:f.HomeTeamId;f.Status=f.WinnerTeamId.HasValue?FixtureStatus.Walkover:FixtureStatus.DoubleForfeit;f.Version++;}await db.SaveChangesAsync();await Audit(db,claims,"withdraw-team","team",teamId,new{affectedFixtures=fixtures.Count});return Results.Ok(new{teamId,affectedFixtures=fixtures.Count});
});

auth.MapGet("/tournaments/{tid:int}/regenerate-fixtures/preview", async(int tid, int withdrawTeamId, ClaimsPrincipal claims, AppDbContext db) =>
{
    if(!IsRole(claims,UserRole.Admin))return Results.Forbid(); var snapshot=await GetRegenerationSnapshotAsync(db,tid,withdrawTeamId); if(snapshot is null)return Results.NotFound(new{message="Tournament or team not found"}); return Results.Ok(new{tournamentId=tid,snapshot.TournamentVersion,withdrawnTeamId=snapshot.WithdrawnTeamId,withdrawnTeamName=snapshot.WithdrawnTeamName,preservedWinnerIds=snapshot.PreservedWinnerIds,preservedWinnerNames=snapshot.PreservedWinnerNames,neverPlayedIds=snapshot.NeverPlayedIds,neverPlayedNames=snapshot.NeverPlayedNames,excludedTeamIds=snapshot.ExcludedTeamIds,excludedTeamNames=snapshot.ExcludedTeamNames,completedFixtureCount=snapshot.CompletedFixtureCount,newFixtureCount=snapshot.ProposedPairings.Count,message=snapshot.ProposedPairings.Count>0?"Preview ready. Completed history will be retained and only the continuation will be regenerated.":"There are not enough eligible teams to create a continuation fixture set."});
});

auth.MapPost("/tournaments/{tid:int}/regenerate-fixtures", async(int tid, RegenerateRequest request, ClaimsPrincipal claims, AppDbContext db) =>
{
    if(!IsRole(claims,UserRole.Admin))return Results.Forbid(); await using var tx=await db.Database.BeginTransactionAsync(); var tournament=await db.Tournaments.SingleOrDefaultAsync(x=>x.Id==tid); if(tournament is null)return Results.NotFound(new{message="Tournament not found"}); if(tournament.Version!=request.ExpectedVersion)return Results.Conflict(new{message="Tournament changed by another admin. Refresh the regeneration preview."}); var snapshot=await GetRegenerationSnapshotAsync(db,tid,request.WithdrawTeamId); if(snapshot is null)return Results.NotFound(new{message="Team not found in this tournament"}); if(snapshot.ProposedPairings.Count<1)return Results.BadRequest(new{message="Not enough eligible teams remain to create a valid continuation bracket."}); var withdrawn=await db.Teams.SingleAsync(x=>x.Id==request.WithdrawTeamId); withdrawn.Status=TeamStatus.Withdrawn; var activeFixtures=await db.Fixtures.Where(x=>x.TournamentId==tid&&(x.Status==FixtureStatus.Pending||x.Status==FixtureStatus.Scheduled||x.Status==FixtureStatus.Bye)).ToListAsync(); db.Fixtures.RemoveRange(activeFixtures); var roundOffset=await db.Fixtures.Where(x=>x.TournamentId==tid).MaxAsync(x=>(int?)x.RoundNo)??0; var created=new List<Fixture>(); foreach(var p in snapshot.ProposedPairings){var fixture=new Fixture{TournamentId=tid,RoundNo=p.RoundNo+roundOffset,Slot=p.Slot,HomeTeamId=p.Home,AwayTeamId=p.Away,Status=p.Bye?FixtureStatus.Bye:FixtureStatus.Pending,WinnerTeamId=p.Bye?(p.Home??p.Away):null}; db.Fixtures.Add(fixture);created.Add(fixture);} tournament.Status="Regenerated";tournament.RegistrationOpen=false;tournament.Version++; await db.SaveChangesAsync(); db.AuditEvents.Add(new AuditEvent{ActorId=UserId(claims),Action="regenerate-fixtures",EntityType="tournament",EntityId=tid,DetailsJson=JsonSerializer.Serialize(new{request.WithdrawTeamId,request.Reason,preservedWinners=snapshot.PreservedWinnerIds,neverPlayed=snapshot.NeverPlayedIds,excluded=snapshot.ExcludedTeamIds,completedFixtureCount=snapshot.CompletedFixtureCount,newFixtureCount=created.Count,roundOffset})}); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new{tournamentId=tid,tournamentVersion=tournament.Version,withdrawnTeamId=snapshot.WithdrawnTeamId,withdrawnTeamName=snapshot.WithdrawnTeamName,preservedWinnerIds=snapshot.PreservedWinnerIds,preservedWinnerNames=snapshot.PreservedWinnerNames,neverPlayedIds=snapshot.NeverPlayedIds,neverPlayedNames=snapshot.NeverPlayedNames,excludedTeamIds=snapshot.ExcludedTeamIds,excludedTeamNames=snapshot.ExcludedTeamNames,completedFixtureCount=snapshot.CompletedFixtureCount,newFixtureCount=created.Count,createdFixtureIds=created.Select(x=>x.Id).ToList(),message="Fixtures regenerated. Completed matches remain historical and are not replayed."});
});

auth.MapPost("/fixtures/{fid:int}/correct", async(int fid, ScoreCorrectionRequest request, ClaimsPrincipal claims, AppDbContext db, IEmailSender email) =>
{
    if(!IsRole(claims,UserRole.Admin)) return Results.Forbid(); var f=await db.Fixtures.FindAsync(fid); if(f is null)return Results.NotFound(); if(f.HomeTeamId is null||f.AwayTeamId is null)return Results.BadRequest(new{message="Fixture is missing participating teams."}); if(f.Version!=request.ExpectedVersion)return Results.Conflict(new{message="Fixture changed by another user. Refresh before correcting."});
    try{f.WinnerTeamId=TournamentEngine.Winner(f.HomeTeamId,f.AwayTeamId,request.HomeScore,request.AwayScore,request.Status);}catch(ArgumentException e){return Results.BadRequest(new{message=e.Message});} f.HomeScore=request.HomeScore; f.AwayScore=request.AwayScore; f.Outcome=request.Outcome; f.Status=Enum.TryParse<FixtureStatus>(request.Status,true,out var st)?st:FixtureStatus.Completed; f.Version++; if(f.WinnerTeamId.HasValue) await AdvanceWinnerAsync(db,f,f.WinnerTeamId.Value); await db.SaveChangesAsync(); await Audit(db,claims,"correct-score","fixture",fid,new{request.Reason,request.HomeScore,request.AwayScore}); await SendFixtureEmailAsync(db,email,fid,"SportsWeek result corrected",false); return Results.Ok(new{fixtureId=fid,version=f.Version,message="Score corrected and downstream bracket refreshed."});
});

auth.MapGet("/audit", async(int? limit, ClaimsPrincipal claims, AppDbContext db)=>{if(!IsRole(claims,UserRole.Admin))return Results.Forbid();return Results.Ok(await db.AuditEvents.OrderByDescending(x=>x.Id).Take(Math.Clamp(limit??200,1,500)).ToListAsync());});

await app.RunAsync();

static object PublicUser(User u)=>new{u.Id,u.Email,u.Name,u.Department,u.Semester,u.EnrollmentNo,u.Section,u.EmailVerified,Role=u.Role.ToString()};
static int UserId(ClaimsPrincipal p)=>int.Parse(p.FindFirstValue(ClaimTypes.NameIdentifier)!);
static bool IsRole(ClaimsPrincipal p, params UserRole[] roles)=>roles.Any(r=>p.IsInRole(r.ToString()));
static async Task AdvanceWinnerAsync(AppDbContext db,Fixture fixture,int winnerId){var next=await db.Fixtures.SingleOrDefaultAsync(x=>x.TournamentId==fixture.TournamentId&&x.RoundNo==fixture.RoundNo+1&&x.Slot==(fixture.Slot+1)/2);if(next is null)return;if(fixture.Slot%2==1)next.HomeTeamId=winnerId;else next.AwayTeamId=winnerId;next.Version++;}
    static async Task<RegenerationSnapshot?> GetRegenerationSnapshotAsync(AppDbContext db,int tournamentId,int withdrawTeamId){var tournament=await db.Tournaments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==tournamentId);var withdrawn=await db.Teams.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==withdrawTeamId&&x.TournamentId==tournamentId&&x.Status==TeamStatus.Approved);if(tournament is null||withdrawn is null)return null;var teams=await db.Teams.AsNoTracking().Where(x=>x.TournamentId==tournamentId&&x.Status==TeamStatus.Approved).OrderBy(x=>x.Id).ToListAsync();var fixtures=await db.Fixtures.AsNoTracking().Where(x=>x.TournamentId==tournamentId).ToListAsync();var historical=fixtures.Where(x=>x.Status is FixtureStatus.Completed or FixtureStatus.Walkover or FixtureStatus.DoubleForfeit or FixtureStatus.Abandoned).ToList();var completedTeamIds=historical.SelectMany(x=>new[]{x.HomeTeamId,x.AwayTeamId}).Where(x=>x.HasValue).Select(x=>x!.Value).ToHashSet();var winnerIds=historical.Where(x=>x.WinnerTeamId.HasValue).Select(x=>x.WinnerTeamId!.Value).ToHashSet();var lostIds=historical.SelectMany(x=>new[]{x.HomeTeamId,x.AwayTeamId}).Where(x=>x.HasValue&&!winnerIds.Contains(x.Value)).Select(x=>x!.Value).ToHashSet();var neverPlayed=teams.Where(x=>!completedTeamIds.Contains(x.Id)&&x.Id!=withdrawTeamId).ToList();var activeIds=winnerIds.Union(neverPlayed.Select(x=>x.Id)).Where(x=>x!=withdrawTeamId&&!lostIds.Contains(x)).Distinct().ToList();var preserved=teams.Where(x=>winnerIds.Contains(x.Id)&&x.Id!=withdrawTeamId&&!lostIds.Contains(x.Id)).ToList();var excluded=teams.Append(withdrawn).Where(x=>!activeIds.Contains(x.Id)).GroupBy(x=>x.Id).Select(x=>x.First()).ToList();var pairings=activeIds.Count>=2?TournamentEngine.GenerateBracket(activeIds):new List<Pairing>();return new RegenerationSnapshot(tournament.Version,withdrawn.Id,withdrawn.Name,preserved.Select(x=>x.Id).ToList(),preserved.Select(x=>x.Name).ToList(),neverPlayed.Select(x=>x.Id).ToList(),neverPlayed.Select(x=>x.Name).ToList(),excluded.Select(x=>x.Id).ToList(),excluded.Select(x=>x.Name).ToList(),historical.Count,pairings);}
static async Task<List<PublicLeaderboardRow>> PublicLeaderboardAsync(AppDbContext db,int? sportId){var teams=await db.Teams.Include(x=>x.Tournament).Where(x=>x.Status==TeamStatus.Approved&&(!sportId.HasValue||x.Tournament!.SportId==sportId.Value)).ToListAsync();var ids=teams.Select(x=>x.Id).ToArray();var fixtures=await db.Fixtures.Where(x=>x.HomeTeamId.HasValue&&x.AwayTeamId.HasValue&&(ids.Contains(x.HomeTeamId.Value)||ids.Contains(x.AwayTeamId.Value))).ToListAsync();return teams.GroupBy(x=>x.Department).Select(g=>new PublicLeaderboardRow(g.Key,g.Sum(t=>fixtures.Count(f=>f.WinnerTeamId==t.Id)),g.Sum(t=>fixtures.Count(f=>f.HomeTeamId==t.Id||f.AwayTeamId==t.Id)),g.Sum(t=>fixtures.Count(f=>f.WinnerTeamId==t.Id))*3,g.Count())).OrderByDescending(x=>x.Points).ThenByDescending(x=>x.Wins).ToList();}
static bool IsGmailAddress(string email){var value=email.Trim().ToLowerInvariant();return (value.EndsWith("@gmail.com")||value.EndsWith("@googlemail.com"))&&new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(value);}
static string CreateVerificationToken()=>Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
static string HashToken(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
static string CreateToken(User user,IConfiguration c,string key){var claims=new[]{new Claim(ClaimTypes.NameIdentifier,user.Id.ToString()),new Claim(ClaimTypes.Role,user.Role.ToString()),new Claim(ClaimTypes.Email,user.Email)};var creds=new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256);var token=new JwtSecurityToken(c["Jwt:Issuer"],c["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(2),signingCredentials:creds);return new JwtSecurityTokenHandler().WriteToken(token);}
static async Task Audit(AppDbContext db,ClaimsPrincipal p,string action,string type,int id,object details){db.AuditEvents.Add(new AuditEvent{ActorId=UserId(p),Action=action,EntityType=type,EntityId=id,DetailsJson=JsonSerializer.Serialize(details)});await db.SaveChangesAsync();}
static async Task SendFixtureEmailAsync(AppDbContext db,IEmailSender email,int fixtureId,string subject,bool upcoming){var f=await db.Fixtures.Include(x=>x.Tournament).ThenInclude(x=>x!.Sport).SingleOrDefaultAsync(x=>x.Id==fixtureId);if(f is null)return;var ids=new[]{f.HomeTeamId,f.AwayTeamId}.Where(x=>x.HasValue).Select(x=>x!.Value).ToArray();var captains=await db.Teams.Where(x=>ids.Contains(x.Id)).Include(x=>x.Captain).Select(x=>x.Captain!.Email).Distinct().ToListAsync();var message=upcoming?$"<p>Your SportsWeek match is scheduled.</p><p><b>Sport:</b> {f.Tournament!.Sport!.Name}<br/><b>Match:</b> Fixture {f.Id}<br/><b>Date/time:</b> {f.StartsAt:u}<br/><b>Venue:</b> {System.Net.WebUtility.HtmlEncode(f.Venue??"To be announced")}</p>":$"<p>A SportsWeek result has been posted.</p><p><b>Sport:</b> {f.Tournament!.Sport!.Name}<br/><b>Fixture:</b> {f.Id}<br/><b>Score:</b> {f.HomeScore} - {f.AwayScore}<br/><b>Status:</b> {f.Status}</p>";foreach(var address in captains)try{await email.SendAsync(address,subject,message);}catch(Exception ex){Console.Error.WriteLine($"Email notification failed for {address}: {ex.Message}");}}
static async Task SeedAsync(AppDbContext db){if(await db.Users.AnyAsync())return;db.Users.AddRange(new User{Email="admin@example.com",Name="Sports Admin",Department="Sports Committee",Semester=1,EnrollmentNo="ADMIN-001",Section="A",PasswordHash=BCrypt.Net.BCrypt.HashPassword("Admin123!"),Role=UserRole.Admin,EmailVerified=true,EmailVerifiedAt=DateTime.UtcNow},new User{Email="scorer@example.com",Name="Event Scorer",Department="Sports Committee",Semester=1,EnrollmentNo="SCORER-001",Section="A",PasswordHash=BCrypt.Net.BCrypt.HashPassword("Scorer123!"),Role=UserRole.Scorer,EmailVerified=true,EmailVerifiedAt=DateTime.UtcNow});foreach(var kv in GameCatalog.Defaults)db.Sports.Add(new Sport{Name=kv.Key,RulesJson=JsonSerializer.Serialize(kv.Value)});await db.SaveChangesAsync();}

